@Test
void rejectsReservationWithoutValidIdentification() throws Exception {
    String noId = """
            {"roomNumber": 201, "guestName": "Someone", "guestEmail": "test@example.com",
             "checkIn": "2027-07-10", "checkOut": "2027-07-12",
             "guests": 2, "ratePlan": "STANDARD"}
            """;
    HttpResponse<String> response = post("/reservations", noId);
    assertEquals(400, response.statusCode());
    assertEquals("INVALID_REQUEST", json.readTree(response.body()).get("error").asText());
}

@Test
void rejectsReservationWithTwoIdentifications() throws Exception {
    String twoIds = """
            {"roomNumber": 201, "guestName": "Someone", "guestEmail": "test@example.com",
             "guestCpf": "111.222.333-44", "companyCnpj": "12.345.678/0001-90", "companyName": "Tech Corp",
             "checkIn": "2027-07-10", "checkOut": "2027-07-12",
             "guests": 2, "ratePlan": "STANDARD"}
            """;
    HttpResponse<String> response = post("/reservations", twoIds);
    assertEquals(400, response.statusCode());
    assertEquals("INVALID_REQUEST", json.readTree(response.body()).get("error").asText());
}

@Test
void acceptsReservationWithCompanyIdentification() throws Exception {
    String companyReservation = """
            {"roomNumber": 201, "guestName": "Ana Silva", "guestEmail": "ana@company.com",
             "companyCnpj": "12.345.678/0001-90", "companyName": "Tech Corp",
             "checkIn": "2027-07-10", "checkOut": "2027-07-12",
             "guests": 2, "ratePlan": "STANDARD"}
            """;
    HttpResponse<String> created = post("/reservations", companyReservation);
    assertEquals(201, created.statusCode());
    JsonNode reservation = json.readTree(created.body());
    assertEquals("PENDING", reservation.get("status").asText());
    assertEquals("Ana Silva", reservation.get("guestName").asText());
    assertEquals("12.345.678/0001-90", reservation.get("companyCnpj").asText());
    assertEquals("Tech Corp", reservation.get("companyName").asText());
}

@Test
void acceptsReservationWithPassportIdentification() throws Exception {
    String passportReservation = """
            {"roomNumber": 201, "guestName": "John Smith", "guestEmail": "john@example.com",
             "guestPassport": "X1234567", "guestCountry": "United Kingdom",
             "checkIn": "2027-07-10", "checkOut": "2027-07-12",
             "guests": 2, "ratePlan": "STANDARD"}
            """;
    HttpResponse<String> created = post("/reservations", passportReservation);
    assertEquals(201, created.statusCode());
    JsonNode reservation = json.readTree(created.body());
    assertEquals("PENDING", reservation.get("status").asText());
    assertEquals("John Smith", reservation.get("guestName").asText());
    assertEquals("X1234567", reservation.get("guestPassport").asText());
    assertEquals("United Kingdom", reservation.get("guestCountry").asText());
}

